import { BrowserRouter as Router, Switch, Route } from "react-router-dom";
import React from 'react';
import './App.css';

import MainPage from "./MainPage";
import RefereePage from "./RefereePage";
import ThoughtsPage from "./ThoughtsPage";
import MiscPage from "./MiscPage";

const App = () => {
  return (
        <main className="dark">
          <Router>
            <Switch>
                <Route path="/thoughts" component={ThoughtsPage} />
                <Route path="/referee" component={RefereePage} />
                <Route path="/misc" component={MiscPage} />
                <Route path="/" component={MainPage} />
            </Switch>
          </Router>
        </main>

  );
}

export default App;
